sys_variable_value.value:
(function execute(inputs, outputs) {
var newDate = inputs.new_date;
var gdNewDate = new GlideDate();
gdNewDate.setDisplayValue(newDate);

var existingDate = inputs.existing_date;
var gdExistingDate = new GlideDate();
gdExistingDate.setDisplayValue(existingDate);

var formattedNewDate = gdNewDate.getByFormat('yyyy-MM');
var formattedExistingDate = gdExistingDate.getByFormat('yyyy-MM');

if (formattedNewDate == formattedExistingDate) {
    outputs.is_same = true;
} else {
    outputs.is_same = false;
}
})(inputs, outputs);

